INSERT INTO `question_options` (`id`, `question_id`, `option_text`, `option_value`, `score`, `is_correct`, `display_order`) VALUES (462, 106, 'Pick the loudest person''s idea to end the argument quickly', 'A', 0.2, 0, 1);
